import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build original target_state lookup (order_id -> dict with status, amount, last_seq)
    orig_state = {}
    for _, row in target_state.iterrows():
        orig_state[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }

    # Working state starts as a copy of the original target_state
    state = {oid: dict(v) for oid, v in orig_state.items()}

    # Track last applied op/seq per order (for tombstone determination)
    last_applied = {}

    # Step 1: dedup events by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset=["seq"], keep="first").copy()

    # Step 2: process events in seq order (seq is the only trusted ordering)
    events = events.sort_values(by="seq", kind="mergesort")

    for _, ev in events.iterrows():
        oid = ev["order_id"]
        seq = ev["seq"]
        op = ev["op"]
        ev_status = ev["status"]
        ev_amount = ev["amount"]

        # Replay guard: based on ORIGINAL target_state only
        if oid in orig_state and seq <= orig_state[oid]["last_seq"]:
            continue

        if op in ("I", "U"):
            if oid in state:
                existing = state[oid]
                if op == "U" and pd.isna(ev_amount):
                    new_amount = existing["amount"]
                else:
                    new_amount = ev_amount
                existing["status"] = ev_status
                existing["amount"] = new_amount
                existing["last_seq"] = seq
            else:
                state[oid] = {
                    "status": ev_status,
                    "amount": ev_amount,
                    "last_seq": seq,
                }
            last_applied[oid] = ("U_OR_I", seq)
        elif op == "D":
            if oid in state:
                del state[oid]
                last_applied[oid] = ("D", seq)
            # else: D on missing order does nothing, last_applied unaffected
        # any other op value: ignore (not specified)

    # Step 3: build new_state from remaining rows in `state`
    if state:
        new_state_rows = []
        for oid, v in state.items():
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": v["status"],
                    "amount": v["amount"],
                    "last_seq": v["last_seq"],
                }
            )
        new_state = pd.DataFrame(new_state_rows, columns=["order_id", "status", "amount", "last_seq"])
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure dtypes align reasonably with inputs
    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype(target_state["order_id"].dtype, errors="ignore")
        new_state["last_seq"] = new_state["last_seq"].astype(target_state["last_seq"].dtype, errors="ignore")

    # Step 4: tombstones - orders whose last applied event was a 'D'
    tomb_rows = []
    for oid, (op, seq) in last_applied.items():
        if op == "D":
            tomb_rows.append({"order_id": oid, "deleted_seq": seq})

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows, columns=["order_id", "deleted_seq"])
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    return {"new_state": new_state, "tombstones": tombstones}
